insert into error_codes (code, module, severity, message_en, fixable_by, playbook) values
  ('AUTH-1001', 'AUTH', 'warning', 'That email or phone number and password don''t match.', 'customer', 'Offer a password reset. Accounts lock after 5 failed tries.'),
  ('AUTH-1002', 'AUTH', 'warning', 'Your account is locked after too many attempts. Try again in 15 minutes or reset your password.', 'customer', 'Confirm identity before unlocking manually.'),
  ('AUTH-1003', 'AUTH', 'warning', 'An account with this email or phone number already exists. Sign in instead.', 'customer', 'Point them to sign-in or password reset; never confirm details over the phone without verification.'),
  ('AUTH-1004', 'AUTH', 'warning', 'Use a password of at least 6 characters.', 'customer', 'Ask them to choose a longer password.'),
  ('AUTH-1005', 'AUTH', 'warning', 'Enter a valid email address or Kenyan phone number.', 'customer', 'Phone numbers: 07…, 01… or +254…. Other countries come later.'),
  ('AUTH-1006', 'AUTH', 'warning', 'Too many attempts. Wait a minute and try again.', 'customer', 'Rate limit per IP address; repeated hits may be an attack, check the logs.'),
  ('AUTH-1007', 'AUTH', 'info',    'Sign in to continue.', 'customer', 'No access token or refresh cookie was sent: the person is not signed in.'),
  ('AUTH-1008', 'AUTH', 'warning', 'Enter your first and last name and choose your role.', 'customer', 'Sign-up form incomplete.'),
  ('AUTH-1009', 'AUTH', 'warning', 'You chose Other: type your role (up to 80 characters).', 'customer', 'Sign-up role "Other" needs the person''s own role.'),
  ('AUTH-1010', 'AUTH', 'info',    'Your session has ended. Sign in again.', 'customer', 'Access token expired, changed or for an ended session, or a refresh failed. Sessions end after 12 hours idle, 7 days total, at sign-out, or when an old refresh token is reused (possible theft: suggest a password change).'),
  ('AUTH-1011',  'AUTH',  'warning', 'This invitation link isn''t valid. Check you opened the whole link, or ask for a new invitation.', 'customer', 'No invitation has this link''s token (mistyped or cut-off link, or an old link replaced by a resend).'),
  ('AUTH-1012',  'AUTH',  'warning', 'This invitation has expired. Ask the person who invited you to send it again.', 'customer', 'Invitation links last 7 days. An administrator resends it from Team access.'),
  ('AUTH-1013',  'AUTH',  'warning', 'This invitation has already been accepted. Sign in instead.', 'customer', 'Links work once.'),
  ('AUTH-1014',  'AUTH',  'warning', 'This invitation was cancelled. Ask the person who invited you if you still need access.', 'customer', 'An administrator revoked it in Team access.'),
  ('AUTH-1015',  'AUTH',  'warning', 'This invitation is for a different email or phone number.', 'customer', 'Only the account with the invitation''s email or phone can accept it.'),
  ('AUTH-1016',  'AUTH',  'warning', 'Enter your first and last name.', 'customer', 'Accepting an invitation for a new account needs a first and last name (up to 60 characters each).'),
  ('PLAT-9002', 'PLAT', 'warning', 'This request came from another website and was blocked.', 'engineering', 'Check App:AllowedOrigins includes the app''s address; otherwise a cross-site request was stopped.'),
  ('ACC-8001',  'ACC',  'warning', 'You don''t have permission to do this. Ask an administrator in your organization.', 'customer', 'Check the person''s role and company scope in the back office.'),
  ('ACC-8002',  'ACC',  'warning', '{name} is already in your organization.', 'customer', 'The email or phone belongs to an active member; change their group in Team access instead.'),
  ('ACC-8003',  'ACC',  'warning', '{contact} already has an invitation waiting. Resend it instead.', 'customer', 'One open invitation per email and per phone in an organization.'),
  ('ACC-8004',  'ACC',  'warning', 'Some invitation details don''t look right. Check the fields marked.', 'customer', 'Name, an email or Kenyan phone number, a group, and all companies or at least one.'),
  ('ACC-8005',  'ACC',  'warning', 'We couldn''t find that invitation. It may have been deleted.', 'customer', 'The invitation doesn''t exist in this organization.'),
  ('ACC-8006',  'ACC',  'warning', 'This invitation was already accepted or cancelled.', 'customer', 'Only open or expired invitations can be resent or cancelled.'),
  ('IMP-3001',  'IMP',  'error',   'Row {row}: {column} is required.', 'customer', 'Point them to the template''s required columns.'),
  ('IMP-3002',  'IMP',  'error',   'Row {row}: "{value}" isn''t one of your {column} options.', 'customer', 'Check the option exists in setup, or fix the spelling.'),
  ('ONB-3501',  'ONB',  'warning', 'Enter your organization''s name (2 to 120 characters).', 'customer', 'Organization step: the name is the one their team knows them by; legal company names come next.'),
  ('ONB-3502',  'ONB',  'warning', 'You already have an organization.', 'customer', 'One onboarded organization per person for now. Accountants and bureaus with several clients go through the partner program.'),
  ('ONB-3503',  'ONB',  'info',    'You haven''t set up your organization yet.', 'customer', 'They signed up but skipped or left the organization step; the app takes them back to it.'),
  ('ONB-3504',  'ONB',  'warning', 'Your account was set up by your organization, so you can''t create a new one. Ask an administrator in your organization.', 'customer', 'Only people who signed up themselves onboard an organization; invited people, staff and partners come in another way.'),
  ('ONB-3505',  'ONB',  'warning', 'Enter the company''s legal name (2 to 160 characters).', 'customer', 'The legal name is empty, too short or too long.'),
  ('ONB-3506',  'ONB',  'warning', 'Pesaroll runs payroll for companies in Kenya. Choose Kenya.', 'customer', 'The country isn''t one Pesaroll runs payroll in yet (countries.available).'),
  ('ONB-3507',  'ONB',  'warning', 'Some details don''t look right. Check the fields marked.', 'customer', 'A company detail failed its check; fields says which (statutory number formats come from the country''s settings).'),
  ('ONB-3508',  'ONB',  'warning', 'You already have a company with this name.', 'customer', 'Another active company in the organization has the same legal name (ignoring case and spaces).'),
  ('ONB-3509',  'ONB',  'warning', 'We couldn''t find that company.', 'customer', 'The company doesn''t exist, was deleted, or belongs to another organization.'),
  ('ONB-3510',  'ONB',  'warning', 'Some paying account details don''t look right. Check the fields marked.', 'customer', 'A paying account detail failed its check; fields says which (bank and branch must be from the list; account number 6 to 20 digits; M-Pesa shortcode 5 to 7 digits).'),
  ('ONB-3511',  'ONB',  'warning', 'We couldn''t find that paying account.', 'customer', 'The account doesn''t exist, was already removed, or belongs to another company or organization.'),
  ('ONB-3512',  'ONB',  'warning', 'Some location details don''t look right. Check the fields marked.', 'customer', 'A location detail failed its check; fields says which (name, code format, county, minimum-wage area, companies, main location).'),
  ('ONB-3513',  'ONB',  'warning', 'Another location already has this code. Choose a different one or leave it empty.', 'customer', 'Location codes are unique in the organization; leaving it empty makes one (MOM-01).'),
  ('ONB-3514',  'ONB',  'warning', 'We couldn''t find that location.', 'customer', 'The location doesn''t exist, was deleted, or belongs to another organization.'),
  ('ONB-3515',  'ONB',  'warning', 'This is the main location of {companies}. Make another location their main location first.', 'customer', 'Every company keeps exactly one main location: it can''t be deleted or unticked until another location is made main.'),
  ('ONB-3516',  'ONB',  'warning', 'We couldn''t read this file. Use the template (.xlsx) or a .csv file with the same columns.', 'customer', 'The upload isn''t an Excel or CSV file, or has no Location name and County columns.'),
  ('ONB-3517',  'ONB',  'warning', 'The file is too big. Upload up to {max} {things} and {MB} MB at a time.', 'customer', 'Locations: 1,000 rows, 2 MB. Divisions, departments, positions and units: 5,000 rows, 5 MB. Split the file.'),
  ('ONB-3518',  'ONB',  'warning', 'Row {n} needs fixing. Check them and try again.', 'customer', 'The rows sent to import failed the checks (they are checked again on import); the review shows each problem in its cell.'),
  ('ONB-3519',  'ONB',  'warning', 'Some details don''t look right. Check the fields marked.', 'customer', 'An org structure detail failed its check; fields says which (name or title, code, division, part of, department, companies).'),
  ('ONB-3520',  'ONB',  'warning', 'Another one already has this code. Choose a different one or leave it empty.', 'customer', 'Codes are unique per level (division, department, position, unit) in the organization.'),
  ('ONB-3521',  'ONB',  'warning', 'We couldn''t find that. It may have been deleted.', 'customer', 'The division, department, position or unit doesn''t exist, was deleted, or belongs to another organization.'),
  ('ONB-3522',  'ONB',  'warning', '{name} still has {what uses it}. Move or delete them first.', 'customer', 'A division with departments, or a department with sub-departments, positions or units, can''t be deleted.'),
  ('ONB-3523',  'ONB',  'warning', 'A department can''t sit under itself or one of its own departments.', 'customer', 'Raised by the database when a department''s parent would make a loop; the API shows it under Part of.'),
  ('ONB-3524',  'ONB',  'warning', 'Some schedule details don''t look right. Check the fields marked.', 'customer', 'A payroll schedule detail failed its check; fields says which (name, frequency, payDayRule, payDay, cutoffDay, payWeekday, firstPayDate, cutoffDaysBefore, cutoffAppliesTo, companyIds, defaultFor, reminders[n].amount, .channel or .recipient). Monthly pay and cut-off days are 1 to 28; weekly and every-two-weeks pay days are Monday to Friday.'),
  ('ONB-3525',  'ONB',  'warning', 'You already have a schedule with this name.', 'customer', 'Schedule names are unique in the organization, ignoring case and spaces.'),
  ('ONB-3526',  'ONB',  'warning', 'We couldn''t find that schedule. It may have been deleted.', 'customer', 'The payroll schedule doesn''t exist, was deleted, or belongs to another organization.'),
  ('ONB-3527',  'ONB',  'warning', 'This is the default schedule of {companies}. Make another schedule their default first.', 'customer', 'Every company keeps one default schedule; tick Default for on another schedule, then delete or untick this one.'),
  ('ONB-3528',  'ONB',  'warning', 'Some details don''t look right. Check the fields marked.', 'customer', 'An earning, deduction or employer cost failed its check; fields says which (name, kind, code, calcMethod, rate, defaultAmount, companyIds).'),
  ('ONB-3529',  'ONB',  'warning', 'Another earning or deduction already has this code. Choose a different one or leave it empty.', 'customer', 'Pay item codes are unique in the organization (stored upper case).'),
  ('ONB-3530',  'ONB',  'warning', 'We couldn''t find that earning or deduction. It may have been deleted.', 'customer', 'The pay item doesn''t exist, was deleted, or belongs to another organization.'),
  ('ONB-3531',  'ONB',  'warning', 'This one is set by law (or is basic pay), so it can''t be changed or deleted.', 'customer', 'Basic pay and statutory items (PAYE, SHIF, NSSF, Housing Levy, NITA) are locked; the database refuses changes too. Rates come from the rule pack (PAY-01).'),
  ('ONB-3532',  'ONB',  'warning', 'Some leave details don''t look right. Check the fields marked.', 'customer', 'A leave type or plan failed its check; fields says which (name, code, counts, whenUsedUp, leaveYear, hoursPerDay, companyIds, defaultFor, defaultForSchedules, rules, rules[n].amount|earnMethod|unit|halfPay|carryOverMax|waitingMonths). Plans can''t give less than the law (statutory_leave): each way of earning is turned into a yearly total.'),
  ('ONB-3533',  'ONB',  'warning', 'You already have {a leave plan with this name / a leave type with this code}. Choose a different one.', 'customer', 'Plan names and type codes are unique in the organization.'),
  ('ONB-3534',  'ONB',  'warning', 'We couldn''t find that leave plan or leave type. It may have been deleted.', 'customer', 'It doesn''t exist, was deleted, or belongs to another organization.'),
  ('ONB-3535',  'ONB',  'warning', 'This leave is set by law, so it can''t be deleted or renamed.', 'customer', 'Statutory leave types (annual, sick, maternity, paternity, pre-adoptive) are locked; the database refuses too. Proof and when-used-up can change.'),
  ('ONB-3536',  'ONB',  'warning', 'This is the default leave plan of {companies}. Make another plan their default first.', 'customer', 'Every company keeps one default leave plan.'),
  ('ONB-3537',  'ONB',  'warning', 'This leave is in {plans}. Take it out of those plans first.', 'customer', 'A leave type in a plan can''t be deleted.'),
  ('ONB-3538',  'ONB',  'warning', 'Some employee details don''t look right. Check the fields marked.', 'customer', 'An employee detail failed its check; fields says which (firstName, lastName, staffNo, phone, email, nationalId, kraPin, nssfNo, shaNo, hireDate, exitDate, dateOfBirth, job.*, pay.*, account.*).'),
  ('ONB-3539',  'ONB',  'warning', 'We couldn''t find that employee. They may have been deleted.', 'customer', 'The employee doesn''t exist, was deleted, or is in a company or organization this person can''t see.'),
  ('ONB-3540',  'ONB',  'warning', '{name (staff number)} already has this {KRA PIN / ID number / NSSF number / SHA number / phone number / email address}. Each current employee has their own.', 'customer', 'Two current employees in an organization can''t share an ID number or KRA PIN (checked through an encrypted lookup), NSSF or SHA number, phone number or email address; this catches a re-import. A former employee''s details can come back on a rehire.'),
  ('ONB-3541',  'ONB',  'warning', '{name} is used by {n} employees. Move them first.', 'customer', 'A department, position, unit, location, payroll schedule or leave plan in employees'' jobs (current or past) can''t be deleted.'),
  ('ONB-3542',  'ONB',  'warning', 'Another employee in this company has this staff number. Choose a different one or leave it empty.', 'customer', 'Staff numbers are unique per company (stored upper case).'),
  ('ONB-3543',  'ONB',  'warning', 'Only .xlsx or .csv files can be imported. {file} is a {.ext} file.', 'customer', 'Uploads are checked by file name first: the template (.xlsx) or a .csv with its columns.'),
  ('ONB-3544',  'ONB',  'warning', 'Invalid file: it doesn''t match the {things} template. Missing columns: … Columns the template doesn''t have: … Download the template and copy your rows into it.', 'customer', 'The first row must have every template column and no others (older date headers without (DD/MM/YYYY) still match). Checked before any row is read.'),
  ('ONB-3545',  'ONB',  'warning', 'This one is set by law (or is basic pay): it applies to everyone, so there''s no one to choose.', 'customer', 'Basic pay and statutory items apply to every employee; only the organization''s own items are given to people.'),
  ('ONB-3546',  'ONB',  'warning', 'This isn''t used by {company}. Add the company to it first.', 'customer', 'An earning or deduction goes only to people at companies it serves.'),
  ('ONB-3547',  'ONB',  'warning', 'Some details of who gets it don''t look right. Check the fields marked.', 'customer', 'People from another company, people who left, someone twice, an amount on a percentage or each-payroll item, or an end before the start.'),
  ('ONB-3548',  'ONB',  'warning', 'Some payee details don''t look right. Check the fields marked.', 'customer', 'Name, the way they''re paid and that way''s details: bank, branch and account number (checked per bank), a 5 to 7 digit paybill, or who cheques are payable to.'),
  ('ONB-3549',  'ONB',  'warning', 'We couldn''t find that payee. It may have been deleted.', 'customer', 'The payee doesn''t exist in this organization.'),
  ('ONB-3550',  'ONB',  'warning', '{name} is the payee of {n} earnings and deductions. Choose another payee for them first.', 'customer', 'A payee in use can''t be deleted.'),
  ('ONB-3551',  'ONB',  'warning', 'Another payee already has this name.', 'customer', 'Payee names are unique in an organization (ignoring case).'),
  ('ONB-3552',  'ONB',  'warning', 'We couldn''t find that payroll history import. It may have been deleted.', 'customer', 'The payroll history batch doesn''t exist, or belongs to a company this person can''t see.'),
  ('NTF-0501',  'NTF',  'warning', 'Enter a valid email address, or a Kenyan mobile number like 0712 345 678.', 'customer', 'A message''s recipient isn''t a Kenyan mobile number (07…, 01…, +254…) or a plain email address.'),
  ('NTF-0502',  'NTF',  'error',   'We couldn''t deliver an email to {recipient}.', 'support', 'Postmark kept refusing it (5 attempts); notification_deliveries.error has its reason (inactive recipient, bounced, bad address). Check the address with the customer.'),
  ('NTF-0503',  'NTF',  'error',   'We couldn''t deliver an SMS to {recipient}.', 'support', 'Africa''s Talking kept refusing it (5 attempts); notification_deliveries.error has its status (blacklisted, invalid number, low balance). Check the number, or the account balance.'),
  ('PAY-2001',  'PAY',  'error',   '{employee} has no KRA PIN, so PAYE can''t be filed.', 'customer', 'Add the KRA PIN on the employee''s profile, then rerun.'),
  ('PAY-2002',  'PAY',  'error',   '{employee}''s pay is below the minimum wage for {location}.', 'customer', 'Confirm pay and location; the run can''t be approved below the minimum.'),
  ('BILL-6001', 'BILL', 'warning', 'This company has more than {limit} active employees. Choose a plan to approve this pay run.', 'customer', 'Explain the plans; check for complimentary access first.'),
  ('PLAT-9001', 'PLAT', 'critical', 'Something went wrong on our side. Quote reference {reference} to support.', 'engineering', 'Look up the reference; escalate with the request id.')
